import { pgTable, text, varchar, integer, timestamp } from "drizzle-orm/pg-core";
import { createInsertSchema } from "drizzle-zod";
import { z } from "zod";

export const users = pgTable("users", {
  id: varchar("id", { length: 36 }).primaryKey(),
  username: text("username").notNull().unique(),
  password: text("password").notNull(),
});

export const insertUserSchema = createInsertSchema(users).pick({
  username: true,
  password: true,
});

export type InsertUser = z.infer<typeof insertUserSchema>;
export type User = typeof users.$inferSelect;

export type PatientStatus = "waiting" | "called" | "in-consultation" | "away" | "completed";

export const departments = [
  "Cardiology",
  "Orthopedics", 
  "Neurology",
  "Pediatrics",
  "General Medicine"
] as const;

export type Department = typeof departments[number];

export interface Patient {
  id: string;
  queueNumber: number;
  name: string;
  phone: string;
  department: Department;
  status: PatientStatus;
  waitTime: number;
  registeredAt: number;
  calledAt?: number;
  doctorName?: string;
  roomNumber?: string;
}

export const insertPatientSchema = z.object({
  name: z.string().min(1, "Name is required"),
  phone: z.string().min(1, "Phone number is required"),
  department: z.enum(departments),
});

export type InsertPatient = z.infer<typeof insertPatientSchema>;

export interface QueueStats {
  total: number;
  waiting: number;
  inConsultation: number;
  completed: number;
  avgWaitTime: number;
}

export type WebSocketMessage = 
  | { type: "PATIENT_REGISTERED"; patient: Patient }
  | { type: "PATIENT_CALLED"; patient: Patient }
  | { type: "PATIENT_STATUS_CHANGED"; patient: Patient }
  | { type: "PATIENT_COMPLETED"; patient: Patient }
  | { type: "QUEUE_UPDATE"; patients: Patient[]; stats: QueueStats }
  | { type: "SYNC_REQUEST" }
  | { type: "PING" }
  | { type: "PONG" };

