import type { Express } from "express";
import { createServer, type Server } from "http";
import { storage } from "./storage";
import { setupWebSocket, notifyPatientRegistered, notifyPatientCalled, notifyPatientStatusChanged, notifyPatientCompleted } from "./websocket";
import { insertPatientSchema, type PatientStatus } from "@shared/schema";
import { z } from "zod";

export async function registerRoutes(app: Express): Promise<Server> {
  app.get("/api/patients", async (_req, res) => {
    try {
      const patients = await storage.getAllPatients();
      res.json(patients);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch patients" });
    }
  });

  app.get("/api/patients/:id", async (req, res) => {
    try {
      const patient = await storage.getPatient(req.params.id);
      if (!patient) {
        return res.status(404).json({ error: "Patient not found" });
      }
      res.json(patient);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch patient" });
    }
  });

  app.get("/api/patients/queue/:queueNumber", async (req, res) => {
    try {
      const queueNumber = parseInt(req.params.queueNumber, 10);
      const patient = await storage.getPatientByQueueNumber(queueNumber);
      if (!patient) {
        return res.status(404).json({ error: "Patient not found" });
      }
      res.json(patient);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch patient" });
    }
  });

  app.get("/api/patients/department/:department", async (req, res) => {
    try {
      const patients = await storage.getPatientsByDepartment(req.params.department);
      res.json(patients);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch patients by department" });
    }
  });

  app.post("/api/patients", async (req, res) => {
    try {
      const data = insertPatientSchema.parse(req.body);
      const patient = await storage.createPatient(data);
      notifyPatientRegistered(patient);
      res.status(201).json(patient);
    } catch (error) {
      if (error instanceof z.ZodError) {
        return res.status(400).json({ error: error.errors });
      }
      res.status(500).json({ error: "Failed to register patient" });
    }
  });

  app.patch("/api/patients/:id/status", async (req, res) => {
    try {
      const { status, doctorName, roomNumber } = req.body as {
        status: PatientStatus;
        doctorName?: string;
        roomNumber?: string;
      };

      if (!status) {
        return res.status(400).json({ error: "Status is required" });
      }

      const patient = await storage.updatePatientStatus(req.params.id, status, { doctorName, roomNumber });

      if (!patient) {
        return res.status(404).json({ error: "Patient not found" });
      }

      if (status === "called") {
        notifyPatientCalled(patient);
      } else if (status === "completed") {
        notifyPatientCompleted(patient);
      } else {
        notifyPatientStatusChanged(patient);
      }

      res.json(patient);
    } catch (error) {
      res.status(500).json({ error: "Failed to update patient status" });
    }
  });

  app.get("/api/stats", async (_req, res) => {
    try {
      const stats = await storage.getQueueStats();
      res.json(stats);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch stats" });
    }
  });

  app.get("/api/next-queue-number", async (_req, res) => {
    try {
      const nextNumber = await storage.getNextQueueNumber();
      res.json({ nextQueueNumber: nextNumber });
    } catch (error) {
      res.status(500).json({ error: "Failed to get next queue number" });
    }
  });

  const httpServer = createServer(app);

  setupWebSocket(httpServer);

  return httpServer;
}

