import { type User, type InsertUser, type Patient, type InsertPatient, type PatientStatus, type QueueStats } from "@shared/schema";
import { randomUUID } from "crypto";

export interface IStorage {
  getUser(id: string): Promise<User | undefined>;
  getUserByUsername(username: string): Promise<User | undefined>;
  createUser(user: InsertUser): Promise<User>;

  getAllPatients(): Promise<Patient[]>;
  getPatient(id: string): Promise<Patient | undefined>;
  getPatientByQueueNumber(queueNumber: number): Promise<Patient | undefined>;
  getPatientsByDepartment(department: string): Promise<Patient[]>;
  getPatientsByStatus(status: PatientStatus): Promise<Patient[]>;
  createPatient(patient: InsertPatient): Promise<Patient>;
  updatePatientStatus(id: string, status: PatientStatus, extras?: { doctorName?: string; roomNumber?: string }): Promise<Patient | undefined>;
  getNextQueueNumber(): Promise<number>;
  getQueueStats(): Promise<QueueStats>;
  clearCompletedPatients(): Promise<void>;
}

export class MemStorage implements IStorage {
  private users: Map<string, User>;
  private patients: Map<string, Patient>;
  private queueCounter: number;

  constructor() {
    this.users = new Map();
    this.patients = new Map();
    this.queueCounter = 1;
  }

  async getUser(id: string): Promise<User | undefined> {
    return this.users.get(id);
  }

  async getUserByUsername(username: string): Promise<User | undefined> {
    return Array.from(this.users.values()).find(
      (user) => user.username === username,
    );
  }

  async createUser(insertUser: InsertUser): Promise<User> {
    const id = randomUUID();
    const user: User = { ...insertUser, id };
    this.users.set(id, user);
    return user;
  }

  async getAllPatients(): Promise<Patient[]> {
    return Array.from(this.patients.values()).sort((a, b) => a.queueNumber - b.queueNumber);
  }

  async getPatient(id: string): Promise<Patient | undefined> {
    return this.patients.get(id);
  }

  async getPatientByQueueNumber(queueNumber: number): Promise<Patient | undefined> {
    return Array.from(this.patients.values()).find(p => p.queueNumber === queueNumber);
  }

  async getPatientsByDepartment(department: string): Promise<Patient[]> {
    return Array.from(this.patients.values())
      .filter(p => p.department === department)
      .sort((a, b) => a.queueNumber - b.queueNumber);
  }

  async getPatientsByStatus(status: PatientStatus): Promise<Patient[]> {
    return Array.from(this.patients.values())
      .filter(p => p.status === status)
      .sort((a, b) => a.queueNumber - b.queueNumber);
  }

  async createPatient(insertPatient: InsertPatient): Promise<Patient> {
    const id = randomUUID();
    const queueNumber = this.queueCounter++;
    const patient: Patient = {
      id,
      queueNumber,
      name: insertPatient.name,
      phone: insertPatient.phone,
      department: insertPatient.department,
      status: "waiting",
      waitTime: 0,
      registeredAt: Date.now(),
    };
    this.patients.set(id, patient);
    return patient;
  }

  async updatePatientStatus(
    id: string, 
    status: PatientStatus, 
    extras?: { doctorName?: string; roomNumber?: string }
  ): Promise<Patient | undefined> {
    const patient = this.patients.get(id);
    if (!patient) return undefined;

    const now = Date.now();
    const updatedPatient: Patient = {
      ...patient,
      status,
      ...(status === "called" ? { calledAt: now } : {}),
      ...(extras?.doctorName ? { doctorName: extras.doctorName } : {}),
      ...(extras?.roomNumber ? { roomNumber: extras.roomNumber } : {}),
      waitTime: Math.round((now - patient.registeredAt) / 60000),
    };

    this.patients.set(id, updatedPatient);
    return updatedPatient;
  }

  async getNextQueueNumber(): Promise<number> {
    return this.queueCounter;
  }

  async getQueueStats(): Promise<QueueStats> {
    const patients = Array.from(this.patients.values());
    const waiting = patients.filter(p => p.status === "waiting").length;
    const inConsultation = patients.filter(p => p.status === "in-consultation").length;
    const completed = patients.filter(p => p.status === "completed").length;

    const waitingPatients = patients.filter(p => p.status === "waiting" || p.status === "in-consultation");
    const avgWaitTime = waitingPatients.length > 0
      ? Math.round(waitingPatients.reduce((sum, p) => sum + p.waitTime, 0) / waitingPatients.length)
      : 0;

    return {
      total: patients.length,
      waiting,
      inConsultation,
      completed,
      avgWaitTime,
    };
  }

  async clearCompletedPatients(): Promise<void> {
    const toDelete: string[] = [];
    this.patients.forEach((patient, id) => {
      if (patient.status === "completed") {
        toDelete.push(id);
      }
    });
    toDelete.forEach(id => this.patients.delete(id));
  }
}

export const storage = new MemStorage();

