import { WebSocketServer, WebSocket } from "ws";
import type { Server } from "http";
import type { Patient, QueueStats, WebSocketMessage } from "@shared/schema";
import { storage } from "./storage";

let wss: WebSocketServer;
const clients = new Set<WebSocket>();

export function setupWebSocket(server: Server): WebSocketServer {
  wss = new WebSocketServer({ server, path: "/ws" });

  wss.on("connection", async (ws: WebSocket) => {
    console.log("New WebSocket client connected");
    clients.add(ws);

    const patients = await storage.getAllPatients();
    const stats = await storage.getQueueStats();
    sendToClient(ws, { type: "QUEUE_UPDATE", patients, stats });

    ws.on("message", async (data: Buffer) => {
      try {
        const message: WebSocketMessage = JSON.parse(data.toString());

        if (message.type === "SYNC_REQUEST") {
          const patients = await storage.getAllPatients();
          const stats = await storage.getQueueStats();
          sendToClient(ws, { type: "QUEUE_UPDATE", patients, stats });
        } else if (message.type === "PING") {
          sendToClient(ws, { type: "PONG" });
        }
      } catch (error) {
        console.error("WebSocket message error:", error);
      }
    });

    ws.on("close", () => {
      console.log("WebSocket client disconnected");
      clients.delete(ws);
    });

    ws.on("error", (error) => {
      console.error("WebSocket error:", error);
      clients.delete(ws);
    });
  });

  return wss;
}

function sendToClient(client: WebSocket, message: WebSocketMessage) {
  if (client.readyState === WebSocket.OPEN) {
    client.send(JSON.stringify(message));
  }
}

export function broadcast(message: WebSocketMessage) {
  const messageStr = JSON.stringify(message);
  clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(messageStr);
    }
  });
}

export async function broadcastQueueUpdate() {
  const patients = await storage.getAllPatients();
  const stats = await storage.getQueueStats();
  broadcast({ type: "QUEUE_UPDATE", patients, stats });
}

export function notifyPatientRegistered(patient: Patient) {
  broadcast({ type: "PATIENT_REGISTERED", patient });
  broadcastQueueUpdate();
}

export function notifyPatientCalled(patient: Patient) {
  broadcast({ type: "PATIENT_CALLED", patient });
  broadcastQueueUpdate();
}

export function notifyPatientStatusChanged(patient: Patient) {
  broadcast({ type: "PATIENT_STATUS_CHANGED", patient });
  broadcastQueueUpdate();
}

export function notifyPatientCompleted(patient: Patient) {
  broadcast({ type: "PATIENT_COMPLETED", patient });
  broadcastQueueUpdate();
}

